# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">GÖK BİLİMİ TARİHİ VE KEPLER\'İN 1. KANUNU (YÖRÜNGELER KANUNU)</text>\n  <!-- Sol: Tarihsel gelisim -->\n  <rect x="25" y="42" width="290" height="202" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="170" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">GÖK BİLİMİNİN ÖNCÜLERİ</text>\n  <text x="38" y="90" font-size="11.5" fill="#1e3a8a">• Batlamyus: Yer (Dünya) merkezli evren modeli</text>\n  <text x="48" y="106" font-size="11" fill="#3b82f6">(Almagest adlı çalışmasıyla uzun süre kabul gördü).</text>\n  <text x="38" y="128" font-size="11.5" fill="#1e3a8a">• Uluğ Bey &amp; Ali Kuşçu: Semerkant Rasathanesi,</text>\n  <text x="48" y="144" font-size="11" fill="#3b82f6">Zîc-i Uluğ Bey (Yıldız kataloğu ve gezegen tabloları).</text>\n  <text x="38" y="166" font-size="11.5" fill="#1e3a8a">• Kopernik: Güneş merkezli (heliosentrik) model.</text>\n  <text x="38" y="188" font-size="11.5" fill="#1e3a8a">• Galileo: Teleskopla Jüpiter uydularını gözlemledi.</text>\n  <text x="38" y="210" font-size="11.5" fill="#1e3a8a">• Tycho Brahe &amp; Kepler: Gezegen yörünge yasaları.</text>\n  <!-- Sag: 1. Kanun -->\n  <rect x="335" y="42" width="340" height="202" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="505" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">1. YÖRÜNGELER KANUNU (ELİPS YÖRÜNGE)</text>\n  <ellipse cx="505" cy="145" rx="135" ry="62" fill="#ffffff" stroke="#b45309" stroke-width="2.5"/>\n  <line x1="370" y1="145" x2="640" y2="145" stroke="#94a3b8" stroke-width="1" stroke-dasharray="4,4"/>\n  <!-- Odak 1: Gunes -->\n  <circle cx="435" cy="145" r="14" fill="#f59e0b" stroke="#dc2626" stroke-width="2"/>\n  <text x="435" y="175" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Güneş (F₁)</text>\n  <!-- Odak 2 -->\n  <circle cx="575" cy="145" r="4" fill="#64748b"/>\n  <text x="575" y="168" text-anchor="middle" font-size="11" fill="#475569">Odak (F₂)</text>\n  <!-- Gezegen -->\n  <circle cx="560" cy="90" r="8" fill="#2563eb"/>\n  <text x="560" y="76" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Gezegen</text>\n  <text x="385" y="135" font-size="10" font-weight="bold" fill="#dc2626">r_min</text>\n  <text x="612" y="135" font-size="10" font-weight="bold" fill="#1d4ed8">r_max</text>\n  <text x="505" y="228" text-anchor="middle" font-size="11.5" fill="#78350f">Her gezegen, odaklarından birinde Güneş bulunan elips yörüngede dolanır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KEPLER\'İN 2. KANUNU: ALANLAR KANUNU VE HIZ DEĞİŞİMİ</text>\n  <!-- Elips Şema -->\n  <rect x="25" y="42" width="350" height="202" rx="10" fill="#ffffff" stroke="#cbd5e1" stroke-width="2"/>\n  <ellipse cx="200" cy="140" rx="145" ry="72" fill="none" stroke="#334155" stroke-width="2"/>\n  <!-- Alan A1 (Sol taraf, Gunese yakin) -->\n  <path d="M 125 140 L 65 105 A 145 72 0 0 0 65 175 Z" fill="#bfdbfe" stroke="#2563eb" stroke-width="1.5"/>\n  <!-- Alan A2 (Sag taraf, Gunese uzak) -->\n  <path d="M 125 140 L 336 118 A 145 72 0 0 1 336 162 Z" fill="#bbf7d0" stroke="#16a34a" stroke-width="1.5"/>\n  <circle cx="125" cy="140" r="13" fill="#f59e0b" stroke="#dc2626" stroke-width="2"/>\n  <text x="125" y="168" text-anchor="middle" font-size="10" font-weight="bold" fill="#9a3412">Güneş</text>\n  <text x="88" y="144" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">A₁</text>\n  <text x="265" y="144" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">A₂</text>\n  <text x="48" y="98" font-size="11" font-weight="bold" fill="#1d4ed8">K</text>\n  <text x="48" y="186" font-size="11" font-weight="bold" fill="#1d4ed8">L (Δt₁)</text>\n  <text x="345" y="115" font-size="11" font-weight="bold" fill="#15803d">M</text>\n  <text x="345" y="170" font-size="11" font-weight="bold" fill="#15803d">N (Δt₂)</text>\n  <text x="200" y="230" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f172a">Δt₁ = Δt₂ ise Taranan Alanlar Eşittir: A₁ = A₂</text>\n  <!-- Sag Açıklama -->\n  <rect x="390" y="42" width="285" height="202" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="532" y="66" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">GÜNEŞ\'E YAKLAŞIRKEN DEĞİŞİMLER</text>\n  <text x="405" y="92" font-size="12" fill="#14532d">• Yörünge yarıçapı (r) AZALIR.</text>\n  <text x="405" y="114" font-size="12" fill="#14532d">• Kütle çekim kuvveti (F) ARTAR.</text>\n  <text x="405" y="136" font-size="12" font-weight="bold" fill="#15803d">• Çizgisel hız (v) ve Kinetik enerji ARTAR.</text>\n  <text x="405" y="158" font-size="12" fill="#14532d">• Potansiyel enerji (Ep) AZALIR.</text>\n  <text x="405" y="180" font-size="12" fill="#14532d">• Eylemsizlik momenti (I = m·r²) AZALIR.</text>\n  <rect x="405" y="194" width="255" height="38" rx="6" fill="#dcfce7" stroke="#22c55e"/>\n  <text x="532" y="211" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">KORUNAN BÜYÜKLÜKLER (Net Tork = 0):</text>\n  <text x="532" y="226" text-anchor="middle" font-size="11.5" fill="#14532d">Açısal Momentum (L) ve Toplam Mekanik Enerji</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KEPLER\'İN 3. KANUNU: PERİYOTLAR KANUNU</text>\n  <!-- Sol Formül Kutusu -->\n  <rect x="30" y="48" width="305" height="190" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">MATEMATİKSEL BAĞINTI</text>\n  <rect x="65" y="92" width="235" height="62" rx="8" fill="#ffffff" stroke="#a855f7" stroke-width="2"/>\n  <text x="182" y="130" text-anchor="middle" font-size="18" font-weight="bold" fill="#581c87">R₁³ / T₁² = R₂³ / T₂² = Sabit</text>\n  <text x="182" y="178" text-anchor="middle" font-size="12" fill="#581c87">Ortalama Yarıçap: R = (r_min + r_max) / 2</text>\n  <text x="182" y="202" text-anchor="middle" font-size="12" fill="#581c87">T: Gezegenin Güneş etrafındaki dolanım periyodu</text>\n  <text x="182" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Aynı yıldız etrafındaki tüm gezegenler için oran sabittir.</text>\n  <!-- Sag Yorum Kutusu -->\n  <rect x="360" y="48" width="310" height="190" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">YARIÇAP - PERİYOT İLİŞKİSİ</text>\n  <text x="378" y="104" font-size="12" fill="#7c2d12">• Güneş\'e yakın gezegenlerin (R küçük):</text>\n  <text x="390" y="122" font-size="12" font-weight="bold" fill="#c2410c">Dolanım periyodu (T) KÜÇÜKTÜR, hızı büyüktür.</text>\n  <text x="378" y="150" font-size="12" fill="#7c2d12">• Güneş\'ten uzak gezegenlerin (R büyük):</text>\n  <text x="390" y="168" font-size="12" font-weight="bold" fill="#c2410c">Dolanım periyodu (T) BÜYÜKTÜR, hızı küçüktür.</text>\n  <rect x="380" y="185" width="270" height="40" rx="6" fill="#ffedd5"/>\n  <text x="515" y="203" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9a3412">Örnek: R_Merkür &lt; R_Dünya &lt; R_Jüpiter</text>\n  <text x="515" y="219" text-anchor="middle" font-size="11.5" fill="#7c2d12">Periyot: T_Merkür &lt; T_Dünya &lt; T_Jüpiter</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
